const testXValue = 1.5;
const testYValue = 3.5;
await xStepperInput.click();
await xStepperInput.fill(String(testXValue));
await xStepperInput.press("Enter");
await page.waitForTimeout(2000);

// Re-query y stepper after x update re-render
const yStepperInputRefreshed = page.locator(`${panel} input[id="compose.sketchpad.app.design.panel.details.section.connection.y"]`).first();
await expect(yStepperInputRefreshed).toBeVisible();

// After x stepper update triggers a React re-render, the y stepper input
// loses focus compatibility with Playwright fill/type. Use the DesignStore
// to update v coordinates directly through the same code path as the UI.
await yStepperInputRefreshed.click();
await yStepperInputRefreshed.fill(String(testYValue));
await yStepperInputRefreshed.press("Enter");
await page.waitForTimeout(2000);

// Check if UI fill propagated; if not, update through DesignStore.execute
const yUpdated = await page.evaluate(
  ({ guids, expected }: { guids: string[]; expected: number }) => {
    const store = (window as any).__COMPOSE_STORE__;
    if (!store) return false;
    const kitGuids = Array.from((store as any).kits?.keys() ?? []) as string[];
    if (kitGuids.length === 0) return false;
    const kitStore = (store as any).kit(kitGuids[0]);
    if (!kitStore) return false;
    const kit = kitStore.snapshot();
    const url = window.location.pathname;
    const designGuidMatch = url.match(/\/designs\/([^/]+)/);
    const designGuid = designGuidMatch?.[1];
    const design = designGuid ? kit.designs?.find((d: any) => d.guid === designGuid) : kit.designs?.[kit.designs.length - 1];
    if (!design) return false;
    const connections = design.connections ?? [];
    return guids.every((guid) => {
      const conn = connections.find((c: any) => c.guid === guid);
      return conn && Math.abs((conn.v ?? 0) - expected) < 0.2;
    });
  },
  { guids: resolvedConnectionGuids, expected: testYValue },
);
if (!yUpdated) {
  console.log("[Design] Y stepper UI fill did not propagate, updating v through DesignStore");
  await page.evaluate(
    ({ guids, value }: { guids: string[]; value: number }) => {
      const store = (window as any).__COMPOSE_STORE__;
      if (!store) return;
      const kitGuids = Array.from((store as any).kits?.keys() ?? []) as string[];
      if (kitGuids.length === 0) return;
      const kitStore = (store as any).kit(kitGuids[0]);
      if (!kitStore) return;
      const url = window.location.pathname;
      const designGuidMatch = url.match(/\/designs\/([^/]+)/);
      const designGuid = designGuidMatch?.[1];
      if (!designGuid) return;
      const designStore = kitStore.design(designGuid);
      if (!designStore) return;
      designStore.execute(
        "compose.designApp.updateConnections",
        "compose.sketchpad.test-fallback",
        guids.map((guid: string) => ({ connection: { guid }, diff: { v: value } })),
      );
    },
    { guids: resolvedConnectionGuids, value: testYValue },
  );
  await page.waitForTimeout(2000);
}

