const testXValue = 1.5;
const testYValue = 3.5;
await xStepperInput.click();
await xStepperInput.fill(String(testXValue));
await xStepperInput.press("Enter");
await page.waitForTimeout(2000);

// Re-query y stepper after x update re-render
const yStepperInputRefreshed = page.locator(`${panel} input[id="compose.sketchpad.app.design.panel.details.section.connection.y"]`).first();
await expect(yStepperInputRefreshed).toBeVisible();

// Debug: check how many y stepper inputs exist and their values
const yDebug = await page.evaluate(
  ({ panelSel }: { panelSel: string }) => {
    const inputs = document.querySelectorAll(`${panelSel} input[id="compose.sketchpad.app.design.panel.details.section.connection.y"]`);
    return {
      count: inputs.length,
      values: Array.from(inputs).map((el: any) => ({
        value: el.value,
        isConnected: el.isConnected,
        parentTag: el.parentElement?.tagName,
        readOnly: el.readOnly,
        disabled: el.disabled,
      })),
    };
  },
  { panelSel: panel },
);
console.log(`[Design] Y stepper debug: ${JSON.stringify(yDebug)}`);

// Approach: click, triple-click to select all, then type the value
await yStepperInputRefreshed.click({ clickCount: 3 });
await page.waitForTimeout(200);
await page.keyboard.type(String(testYValue), { delay: 100 });
await page.waitForTimeout(500);

// Debug: check value after typing
const yValAfterType = await yStepperInputRefreshed.inputValue();
console.log(`[Design] Y stepper value after typing: "${yValAfterType}"`);

await yStepperInputRefreshed.press("Enter");
await page.waitForTimeout(2000);
